input.query:
*[_type == "planet" && name match "Kepler-139*"]{
  _id,
  name,
  "defaultSet": defaultParameterSet->{
    _id,
    defaultFlag,
    "paper": publication->citation,
    radiusEarth,
    massEarth,
    massKind
  },
  "sets": parameterSets[]->{
    _id,
    defaultFlag,
    "paper": publication->citation,
    radiusEarth,
    massEarth,
    massKind
  }
}

*[_type == "planet" && name match "Proxima*"]{
  _id,
  name,
  "defaultSetId": defaultParameterSet._ref,
  "defaultSet": defaultParameterSet->{
    _id,
    massEarth,
    radiusEarth,
    publication->{citation}
  },
  "sets": parameterSets[]->{
    _id,
    defaultFlag,
    massEarth,
    radiusEarth,
    "paper": publication->citation
  }
}
